def solve():
    edges = []
    for g in range(5):
        edges.append((g*2, g*2+1))
    for g in range(4):
        edges.append((g*2, (g+1)*2))
        edges.append((g*2+1, (g+1)*2+1))

    print("Edges:", edges)
    print("Num edges:", len(edges))

    # Backtracking
    labels = [-1] * 10
    used_labels = set()
    used_diffs = set()

    def backtrack(idx):
        if idx == 10:
            return True

        for l in range(14):
            if l in used_labels:
                continue

            # Check if we can assign l to vertex idx
            labels[idx] = l

            # Check edges that are fully assigned
            valid = True
            new_diffs = []
            for u, v in edges:
                if u <= idx and v <= idx:
                    if u == idx or v == idx:
                        diff = abs(labels[u] - labels[v])
                        if diff in used_diffs or diff in new_diffs or diff == 0:
                            valid = False
                            break
                        new_diffs.append(diff)

            if valid:
                used_labels.add(l)
                for d in new_diffs:
                    used_diffs.add(d)

                if backtrack(idx + 1):
                    return True

                used_labels.remove(l)
                for d in new_diffs:
                    used_diffs.remove(d)

        labels[idx] = -1
        return False

    if backtrack(0):
        print("Solution:", labels)
    else:
        print("UNSATISFIABLE")

solve()
